command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="eccc723ce730b49be79626cf2e5794d1e2a9fabc"
$candidate="a48ffcda7c52eadc056eef48360d6d641ff7c153"
$builtBaseline="b137a9f7f6882dbd7dddc43953dc0fcdb2b6e624"
$branch="work/metadata-sort-baseline-harness-20261006"
$runtime="C:\dev\flyExplorer\logs\metadata-sort-baseline-runtime-b137a9f7"
$temp=Join-Path $env:RUNNER_TEMP ("fly-metadata-baseline-gui-"+$env:GITHUB_RUN_ID)
$evidence=Join-Path $repo "logs\remote-evidence"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "metadata baseline GUI fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before metadata baseline GUI"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "metadata baseline branch moved"}
& git diff --quiet ($main+"..."+$candidate) -- app/winui src/base build.bat run.bat
if($LASTEXITCODE -ne 0){throw "baseline harness branch changed product files"}
& git diff --quiet ($builtBaseline+".."+$candidate) -- app/winui src/base build.bat run.bat
if($LASTEXITCODE -ne 0){throw "baseline product changed after cached build"}
$exe=Join-Path $runtime "flyExplorer.exe"
if(!(Test-Path -LiteralPath $exe)){throw "cached baseline executable missing"}
& git worktree add --detach $temp $candidate
if($LASTEXITCODE -ne 0){throw "metadata baseline GUI worktree creation failed"}
try{
  Set-Location -LiteralPath $temp
  & git diff --check ($main+"..."+$candidate)
  if($LASTEXITCODE -ne 0){throw "metadata baseline GUI diff check failed"}
  & python -X utf8 tests\winui\test_metadata_sort_gui.py --configuration Release --exe $exe --expect-legacy-fallback --capture before
  if($LASTEXITCODE -ne 0){throw "metadata baseline GUI resume failed"}
  Write-Host "METADATA_SORT_BASELINE_GUI=PASS"
  New-Item -ItemType Directory -Path $evidence -Force | Out-Null
  Copy-Item -LiteralPath (Join-Path $temp "logs\metadata-sort\metadata-sort-before.png") -Destination (Join-Path $evidence "metadata-sort-before.png") -Force
  Write-Host "METADATA_SORT_BASELINE_VISUAL=EXPORTED"
} finally {
  Set-Location -LiteralPath $repo
  & git worktree remove $temp --force
}
